// Who lives where. Weights per biome — no bison in the rainforest, and the
// desert is horse country.
const HERD_MIX: Record<string, number[]> = {
  arid: [3, 1, 5], tropical: [7, 0, 2], temperate: [5, 3, 3], boreal: [6, 4, 1], alpine: [5, 3, 3],
};
