      for (const c of r.cps) if (Math.hypot(c.x - x, c.z - z) < SURVEY_DEDUP) { dup = true; break; }
      if (dup) continue;
      const key = cpKey(x, z);
      const got = surveyStore.took(id, key);
      r.cps.push({ x, z, key, got });
      if (got) r.got++;
