  const url = `${location.pathname}?run=${user}/${id}`;
  if (real.on || lineOn || hopping) { location.replace(url); return; }
  attractStop();
  menu.open(T_DRIVE);
  const w = await runFetchWire(user, id);
  if (!w) return;
