        // moves it by centimetres at most.
        const k = `${Math.round(x)},${Math.round(z)}`;
        const e = ends.get(k) ?? [];
        e.push({ y, fd: sg.fd ?? -1, nm: sg.nm ?? '?', hw: sg.hw, pb: sg.pb ?? -1 });
        ends.set(k, e);
