  // back signed in, on the URL they left, and takes the docket with a second
  // tap — free drive never asks for any of this.
  if (!sync.signedIn()) { void sync.signIn(); return; }
  const st = lineLoad();
  if (st) {
    travelTo(st.lat, st.lon, st.h,
      `${location.pathname}?lat=${st.lat}&lon=${st.lon}&h=${st.h}&cam=chase&line=1`, { line: true });
    return;
  }
  if (!LINE_START) return;
  try {
    localStorage.setItem(LINE_KEY, JSON.stringify({
      lat: LINE_START.lat, lon: LINE_START.lon, h: LINE_START.h,
      odo: 0, begunAt: Date.now(), at: Date.now(),
    } satisfies LineState));
  } catch { /* still playable; CONTINUE just will not know the metre */ }
